CREATE OR REPLACE FUNCTION public.ingest_phishing_scan(p_payload jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_scan_id           uuid;
  v_model_id          uuid;
  v_prediction_id     uuid;
  v_rag_assessment_id uuid;
  v_analysis_run_id   uuid;

  v_scan      jsonb := COALESCE(p_payload->'url_scans', p_payload->'URL Scan (public.url_scans)');
  v_char      jsonb := COALESCE(p_payload->'char_count_features', p_payload->'Character Counts (public.char_count_features)');
  v_struct    jsonb := COALESCE(p_payload->'url_structure_features', p_payload->'URL Structure (public.url_structure_features)');
  v_host_raw  jsonb := COALESCE(p_payload->'host_features', p_payload->'Host & Domain (public.host_features)', p_payload->'Host & Domain (public)');
  v_host      jsonb := COALESCE(v_host_raw->'host_features', v_host_raw);
  v_word_raw  jsonb := COALESCE(p_payload->'word_features', p_payload->'Word Statistics (public.word_features)', p_payload->'Word Statistics (public)');
  v_word      jsonb := COALESCE(v_word_raw->'word_features', v_word_raw);
  v_brand_raw jsonb := COALESCE(p_payload->'brand_features', p_payload->'Brand Signals (public.brand_features)');
  v_brand     jsonb := COALESCE(v_brand_raw->'brand_features', v_brand_raw);
  v_cont_raw  jsonb := COALESCE(p_payload->'content_features', p_payload->'Page Content (public.content_features)', p_payload->'Page Content (public)');
  v_content   jsonb := COALESCE(v_cont_raw->'content_features', v_cont_raw);
  v_rep       jsonb := COALESCE(p_payload->'reputation_features', p_payload->'Reputation & WHOIS (public.reputation_features)');
  v_pred      jsonb := COALESCE(p_payload->'predictions', p_payload->'ML Prediction (public.predictions)');
  v_model     jsonb := COALESCE(v_pred->'_model_metadata', p_payload->'ml_models', p_payload->'ML Model (public.ml_models)');
  v_rag       jsonb := COALESCE(p_payload->'rag_assessments', p_payload->'RAG Assessment (public.rag_assessments)');
  v_run       jsonb := COALESCE(p_payload->'analysis_runs', p_payload->'Analysis Run (public.analysis_runs)');
BEGIN
  -- 1. Insert URL Scan
  INSERT INTO public.url_scans (url, status, source, scanned_at, created_at)
  VALUES (
    v_scan->>'url',
    COALESCE(NULLIF(v_scan->>'status', ''), 'scraped_ok'),
    COALESCE(NULLIF(v_scan->>'source', ''), 'api'),
    COALESCE((v_scan->>'scanned_at')::timestamptz, NOW()),
    COALESCE((v_scan->>'created_at')::timestamptz, NOW())
  )
  RETURNING id INTO v_scan_id;

  -- 2. Insert Character Counts
  IF v_char IS NOT NULL AND v_char <> '{}'::jsonb THEN
    INSERT INTO public.char_count_features (scan_id, nb_dots, nb_qm, nb_eq, nb_slash, nb_www)
    VALUES (
      v_scan_id,
      (v_char->>'nb_dots')::int4,
      (v_char->>'nb_qm')::int4,
      (v_char->>'nb_eq')::int4,
      (v_char->>'nb_slash')::int4,
      (v_char->>'nb_www')::int4
    );
  END IF;

  -- 3. Insert URL Structure
  IF v_struct IS NOT NULL AND v_struct <> '{}'::jsonb THEN
    INSERT INTO public.url_structure_features (scan_id, length_url, ip, ratio_digits_url, prefix_suffix)
    VALUES (
      v_scan_id,
      (v_struct->>'length_url')::int4,
      (v_struct->>'ip')::bool,
      (v_struct->>'ratio_digits_url')::float8,
      (v_struct->>'prefix_suffix')::bool
    );
  END IF;

  -- 4. Insert Host & Domain
  IF v_host IS NOT NULL AND v_host <> '{}'::jsonb THEN
    INSERT INTO public.host_features (scan_id, length_hostname, ratio_digits_host, tld_in_subdomain)
    VALUES (
      v_scan_id,
      (v_host->>'length_hostname')::int4,
      (v_host->>'ratio_digits_host')::float8,
      (v_host->>'tld_in_subdomain')::bool
    );
  END IF;

  -- 5. Insert Word Statistics
  IF v_word IS NOT NULL AND v_word <> '{}'::jsonb THEN
    INSERT INTO public.word_features (scan_id, shortest_word_host, longest_words_raw, longest_word_path, phish_hints)
    VALUES (
      v_scan_id,
      (v_word->>'shortest_word_host')::int4,
      (v_word->>'longest_words_raw')::int4,
      (v_word->>'longest_word_path')::int4,
      (v_word->>'phish_hints')::int4
    );
  END IF;

  -- 6. Insert Brand Signals (only if non-null values exist)
  IF v_brand IS NOT NULL AND (
    v_brand->>'domain_in_brand' IS NOT NULL
    OR v_brand->>'brand_in_subdomain' IS NOT NULL
    OR v_brand->>'brand_in_path' IS NOT NULL
  ) THEN
    INSERT INTO public.brand_features (scan_id, domain_in_brand, brand_in_subdomain, brand_in_path)
    VALUES (
      v_scan_id,
      (v_brand->>'domain_in_brand')::bool,
      (v_brand->>'brand_in_subdomain')::int4,
      (v_brand->>'brand_in_path')::int4
    );
  END IF;

  -- 7. Insert Page Content
  IF v_content IS NOT NULL AND v_content <> '{}'::jsonb THEN
    INSERT INTO public.content_features (scan_id, nb_hyperlinks, "ratio_intHyperlinks", empty_title, domain_in_title)
    VALUES (
      v_scan_id,
      (v_content->>'nb_hyperlinks')::int4,
      (v_content->>'ratio_intHyperlinks')::float8,
      (v_content->>'empty_title')::bool,
      (v_content->>'domain_in_title')::bool
    );
  END IF;

  -- 8. Insert Reputation & WHOIS
  IF v_rep IS NOT NULL AND v_rep <> '{}'::jsonb THEN
    INSERT INTO public.reputation_features (scan_id, domain_age, google_index, page_rank)
    VALUES (
      v_scan_id,
      NULLIF((v_rep->>'domain_age')::int4, -1),
      (v_rep->>'google_index')::bool,
      (v_rep->>'page_rank')::int4
    );
  END IF;

  -- 9. Lookup or Insert ML Model
  SELECT id INTO v_model_id
  FROM public.ml_models
  WHERE model_name = COALESCE(NULLIF(v_model->>'model_name', ''), 'Echonet1.0')
    AND version = COALESCE(NULLIF(v_model->>'version', ''), 'v1.01')
  LIMIT 1;

  IF v_model_id IS NULL THEN
    INSERT INTO public.ml_models (model_name, algorithm, version, accuracy, trained_at)
    VALUES (
      COALESCE(NULLIF(v_model->>'model_name', ''), 'Echonet1.0'),
      COALESCE(NULLIF(v_model->>'algorithm', ''), 'RandomForestClassifier'),
      COALESCE(NULLIF(v_model->>'version', ''), 'v1.01'),
      (v_model->>'accuracy')::float8,
      NOW()
    )
    RETURNING id INTO v_model_id;
  END IF;

  -- 10. Insert ML Prediction
  INSERT INTO public.predictions (scan_id, model_id, threat_pct, predicted_status, predicted_at)
  VALUES (
    v_scan_id,
    v_model_id,
    (v_pred->>'threat_pct')::float8,
    v_pred->>'predicted_status',
    COALESCE((v_pred->>'predicted_at')::timestamptz, NOW())
  )
  RETURNING id INTO v_prediction_id;

  -- 11. Insert RAG Assessment
  INSERT INTO public.rag_assessments (scan_id, llm_model, threat_pct, explanation, created_at)
  VALUES (
    v_scan_id,
    v_rag->>'llm_model',
    (v_rag->>'threat_pct')::float8,
    v_rag->>'explanation',
    COALESCE((v_rag->>'created_at')::timestamptz, NOW())
  )
  RETURNING id INTO v_rag_assessment_id;

  -- 12. Insert Analysis Run (Final Verdict)
  INSERT INTO public.analysis_runs (prediction_id, rag_assessment_id, final_threat_pct, verdict, decided_by, created_at)
  VALUES (
    v_prediction_id,
    v_rag_assessment_id,
    (v_run->>'final_threat_pct')::float8,
    v_run->>'verdict',
    v_run->>'decided_by',
    COALESCE((v_run->>'created_at')::timestamptz, NOW())
  )
  RETURNING id INTO v_analysis_run_id;

  RETURN jsonb_build_object(
    'scan_id', v_scan_id,
    'model_id', v_model_id,
    'prediction_id', v_prediction_id,
    'rag_assessment_id', v_rag_assessment_id,
    'analysis_run_id', v_analysis_run_id
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.ingest_phishing_scan(jsonb) TO service_role;

