// FR-01 / FR-02: capture the WhatsApp message, extract every URL, normalise and validate them.
const incoming = $input.first().json;
// Guardrails only outputs { guardrailsInput, checks }, so recover the original row from Insert row.
let row = {};
try { row = $('Update Status to Ready For Review').first().json ?? {}; } catch (e) { row = {}; }
const raw = { ...row, ...incoming };
if (!raw.Message && !raw.message && !raw.chatInput && incoming.guardrailsInput) raw.Message = incoming.guardrailsInput;

// The WhatsApp Trigger emits the `value` object of the Cloud API webhook; handle a raw webhook body too.
let value = raw.messages ? raw : (raw.entry?.[0]?.changes?.[0]?.value ?? raw.body?.entry?.[0]?.changes?.[0]?.value ?? {});

// Flat row from the chat/data-table path (Message, Phone, Sender, MessageId, SessionId)
if (!value.messages && (raw.Message || raw.message || raw.chatInput)) {
  value = {
    messages: [{ from: raw.Phone ?? raw.phone ?? '', id: raw.MessageId ?? raw.messageId ?? '', text: { body: String(raw.Message ?? raw.message ?? raw.chatInput) } }],
    contacts: [{ profile: { name: raw.Sender ?? raw.sender ?? '' } }],
    metadata: { phone_number_id: raw.SessionId ?? raw.sessionId },
  };
}

const msg = value.messages?.[0];
if (!msg) return []; // delivery/read status callbacks - nothing to do

const waPhone = msg.from;
const name = value.contacts?.[0]?.profile?.name ?? '';
const phoneNumberId = value.metadata?.phone_number_id;
const text = msg.text?.body ?? msg.button?.text ?? msg.interactive?.button_reply?.title ?? msg.image?.caption ?? '';

const base = { waPhone, name, phoneNumberId, messageId: msg.id, messageText: text, receivedAt: new Date().toISOString() };

const MAX_URLS = 5;
const MAX_URL_LENGTH = 2048;
const ANALYSABLE_SCHEMES = new Set(['http', 'https']);

// Look like domains but are almost always file names in chat ("report.pdf").
const FILE_EXTENSIONS = new Set(['pdf', 'txt', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx', 'csv',
  'jpg', 'jpeg', 'png', 'gif', 'webp', 'heic', 'js', 'json', 'py', 'exe', 'html', 'htm']);

// Schemes that have no "//" and would otherwise be missed. Their presence is itself a red flag.
const DANGEROUS_RE = /\b(?:javascript|vbscript):|\bdata:[a-z]+\/[a-z0-9.+-]+[;,]|\b(?:file|smb):[\/\\]{2}|\b(?:ms-[a-z0-9-]+|search-ms):|\\\\[a-z0-9.-]+\\/gi;

// 1) explicit scheme://...   2) bare domain or IPv4 (captured so it can be flagged as MISSING_SCHEME)
const URL_RE = /(?<![\p{L}\p{N}+.-])([a-z][a-z0-9+.-]*:[\/\\]{2}[^\s<>"'`]+)|(?<![@\p{L}\p{N}.\/\\:-])((?:[\p{L}\p{N}](?:[\p{L}\p{N}-]*[\p{L}\p{N}])?\.)+\p{L}{2,63}(?::\d{1,5})?(?:[\/?#\\][^\s<>"'`]*)?|\d{1,3}(?:\.\d{1,3}){3}(?::\d{1,5})?(?:[\/?#\\][^\s<>"'`]*)?)(?![\p{L}\p{N}@-])/giu;

const IPV4_RE = /^(?:(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)$/;
const LEGACY_IP_RE = /^(?:0x[0-9a-f]+|\d+)(?:\.(?:0x[0-9a-f]+|\d+)){0,3}$/i;
const DOMAIN_RE = /^(?:[\p{L}\p{N}](?:[\p{L}\p{N}-]{0,61}[\p{L}\p{N}])?\.)+(?:\p{L}{2,63}|xn--[a-z0-9-]{2,59})$/u;
const PRIVATE_NAME_RE = /(?:^|\.)(?:localhost|local|internal|lan|home\.arpa)$/;

function trimTrailing(s) {
  let out = s;
  for (;;) {
    const last = out.slice(-1);
    if (/[.,;:!?'"\]}>*_~]/.test(last)) { out = out.slice(0, -1); continue; }
    if (last === ')' && out.split('(').length < out.split(')').length) { out = out.slice(0, -1); continue; }
    return out;
  }
}

function decodeLegacyIpv4(h) {
  const nums = h.split('.').map(s =>
    /^0x/i.test(s) ? parseInt(s.slice(2), 16)
    : /^0[0-7]+$/.test(s) ? parseInt(s, 8)
    : /^0\d/.test(s) ? NaN
    : parseInt(s, 10));
  if (nums.some(Number.isNaN)) return null;
  const last = nums.pop();
  if (nums.some(n => n > 255) || last >= 256 ** (4 - nums.length)) return null;
  const v = nums.reduce((acc, n, i) => acc + n * 256 ** (3 - i), 0) + last;
  return [24, 16, 8, 0].map(s => Math.floor(v / 2 ** s) % 256).join('.');
}

function isPrivateIpv4(ip) {
  const [a, b] = ip.split('.').map(Number);
  return a === 0 || a === 10 || a === 127 ||
    (a === 169 && b === 254) || (a === 172 && b >= 16 && b <= 31) || (a === 192 && b === 168) ||
    (a === 100 && b >= 64 && b <= 127) ||
    a >= 224;
}

function parseIpv6(bracketed) {
  if (!bracketed.startsWith('[') || !bracketed.endsWith(']')) return null;
  let inner = bracketed.slice(1, -1);
  if (!inner) return null;

  const lastColon = inner.lastIndexOf(':');
  if (lastColon !== -1 && inner.slice(lastColon + 1).includes('.')) {
    const v4 = inner.slice(lastColon + 1);
    if (!IPV4_RE.test(v4)) return null;
    const [a, b, c, d] = v4.split('.').map(Number);
    inner = inner.slice(0, lastColon + 1) + ((a << 8) | b).toString(16) + ':' + ((c << 8) | d).toString(16);
  }

  const halves = inner.split('::');
  if (halves.length > 2) return null;

  const parseParts = s => (s === '' ? [] : s.split(':'));
  const left = parseParts(halves[0]);
  const right = halves.length === 2 ? parseParts(halves[1]) : [];
  if ([...left, ...right].some(p => !/^[0-9a-f]{1,4}$/i.test(p))) return null;

  const missing = 8 - (left.length + right.length);
  if (halves.length === 1 ? missing !== 0 : missing < 1) return null;

  return [...left, ...Array(missing).fill('0'), ...right].map(p => parseInt(p, 16));
}

function isPrivateIpv6(hextets) {
  const isAllZero = hextets.every(h => h === 0);
  const isLoopback = hextets.slice(0, 7).every(h => h === 0) && hextets[7] === 1;
  const isUla = (hextets[0] & 0xfe00) === 0xfc00;
  const isLinkLocal = (hextets[0] & 0xffc0) === 0xfe80;
  const isMulticast = (hextets[0] & 0xff00) === 0xff00;
  const isIpv4Mapped = hextets.slice(0, 5).every(h => h === 0) && hextets[5] === 0xffff;
  if (isIpv4Mapped) {
    const mappedIp = [hextets[6] >> 8, hextets[6] & 0xff, hextets[7] >> 8, hextets[7] & 0xff].join('.');
    return isPrivateIpv4(mappedIp);
  }
  return isAllZero || isLoopback || isUla || isLinkLocal || isMulticast;
}

function analyse({ submittedUrl, hasScheme }) {
  const signals = [];
  const out = (status, extra = {}) => ({ submittedUrl, status, signals, ...extra });

  if (submittedUrl.length > MAX_URL_LENGTH) return out('TOO_LONG');

  // Strictly require an explicit scheme/protocol; never auto-prepend https://
  if (!hasScheme) return out('MISSING_SCHEME');

  const sm = submittedUrl.match(/^([a-z][a-z0-9+.-]*):[\/\\]{2,}(.*)$/is);
  if (!sm) return out('MALFORMED');
  const scheme = sm[1].toLowerCase();
  if (!ANALYSABLE_SCHEMES.has(scheme)) return out('UNSUPPORTED_SCHEME', { scheme });

  let rest = sm[2];
  if (rest.includes('\\')) { signals.push('backslash-in-url'); rest = rest.replace(/\\/g, '/'); }

  const p = rest.match(/^([^\/?#]*)([^?#]*)(\?[^#]*)?(#.*)?$/s);
  let authority = p[1];
  const path = p[2] || '';       // Do not invent a trailing "/" if none was in the original URL
  const query = p[3] || '';
  const fragment = p[4] || '';
  if (/[\x00-\x1f\x7f]/.test(path + query + fragment)) return out('MALFORMED', { scheme });

  let userinfo = '';
  const at = authority.lastIndexOf('@');
  if (at !== -1) {
    userinfo = authority.slice(0, at);
    authority = authority.slice(at + 1);
    signals.push('userinfo-in-url');
    if (/[a-z0-9-]+\.[a-z]{2,}/i.test(userinfo)) signals.push('userinfo-looks-like-domain');
  }

  const hp = authority.match(/^(\[[0-9a-f:.]+\]|[^:]*)(?::(\d*))?$/i);
  if (!hp) return out('MALFORMED', { scheme });
  let host = hp[1].toLowerCase().replace(/\.$/, '');
  let port = hp[2] ? String(Number(hp[2])) : '';
  if (port && !(Number(port) >= 1 && Number(port) <= 65535)) return out('INVALID_PORT', { scheme, host });
  if (port === (scheme === 'https' ? '443' : '80')) port = '';
  if (port) signals.push('non-standard-port');

  if (host.includes('%')) {
    try { host = decodeURIComponent(host).toLowerCase(); signals.push('percent-encoded-host'); }
    catch (e) { return out('MALFORMED', { scheme }); }
  }

  let hostType;
  let resolvedIpv4 = null;
  if (host.startsWith('[')) {
    const ipv6Hextets = parseIpv6(host);
    if (!ipv6Hextets) return out('INVALID_HOST', { scheme, host });
    hostType = 'ipv6';
    signals.push('ip-literal-host');
    if (isPrivateIpv6(ipv6Hextets)) return out('PRIVATE_HOST', { scheme, host });
  } else if (IPV4_RE.test(host)) {
    hostType = 'ipv4';
    resolvedIpv4 = host;
    signals.push('ip-literal-host');
  } else if (LEGACY_IP_RE.test(host)) {
    resolvedIpv4 = decodeLegacyIpv4(host);
    if (!resolvedIpv4) return out('INVALID_HOST', { scheme, host });
    hostType = 'ipv4';
    signals.push('ip-literal-host', 'obfuscated-ip-host');
  } else if (host === 'localhost' || PRIVATE_NAME_RE.test(host)) {
    return out('PRIVATE_HOST', { scheme, host });
  } else {
    const hostWithoutWww = host.replace(/^www\./, '');
    if (host.length <= 253 && DOMAIN_RE.test(hostWithoutWww)) {
      hostType = 'domain';
      if (/[^\x00-\x7f]/.test(host)) signals.push('non-ascii-host');
      if (/(?:^|\.)xn--/.test(host)) signals.push('punycode-host');
    } else {
      return out('INVALID_HOST', { scheme, host });
    }
  }
  if (resolvedIpv4 && isPrivateIpv4(resolvedIpv4)) return out('PRIVATE_HOST', { scheme, host });

  const normalisedHost = resolvedIpv4 || host;
  const normalisedUrl = `${scheme}://${normalisedHost}${port ? ':' + port : ''}${path}${query}${fragment}`;
  return out('OK', { normalisedUrl, scheme, host, hostType, port, path, query, fragment, userinfo, resolvedIpv4 });
}

// ---------- Extract every link, not just the first ----------
const dangerousSchemes = [...new Set([...text.matchAll(DANGEROUS_RE)].map(m => m[0].toLowerCase()))];

const candidates = [];
const seen = new Set();
for (const m of text.matchAll(URL_RE)) {
  const hasScheme = Boolean(m[1]);
  const cleaned = trimTrailing(m[0]);
  if (!cleaned || seen.has(cleaned)) continue;
  if (!hasScheme) {
    const tld = cleaned.split(/[\/?#:\\]/)[0].split('.').pop();
    if (FILE_EXTENSIONS.has(tld.toLowerCase())) continue;
    if (/[A-Z]/.test(tld) && tld !== tld.toUpperCase()) continue;
  }
  seen.add(cleaned);
  candidates.push({ submittedUrl: cleaned, hasScheme });
  if (candidates.length >= MAX_URLS) break;
}

const urls = candidates.map(analyse);
const primary = urls.find(u => u.status === 'OK');

if (!urls.length) {
  return [{ json: { ...base, valid: false, reason: dangerousSchemes.length ? 'DANGEROUS_SCHEME' : 'NO_URL', dangerousSchemes, urls } }];
}
if (!primary) {
  const reason = dangerousSchemes.length ? 'DANGEROUS_SCHEME' : urls[0].status;
  return [{ json: { ...base, valid: false, reason, submittedUrl: urls[0].submittedUrl, dangerousSchemes, urls } }];
}
return [{ json: {
  ...base,
  valid: true,
  submittedUrl: primary.submittedUrl,
  normalisedUrl: primary.normalisedUrl,
  scheme: primary.scheme,
  host: primary.host,
  path: primary.path,
  query: primary.query,
  fragment: primary.fragment,
  signals: primary.signals,
  dangerousSchemes,
  urls,
} }];

