// Feature engineering for the Random Forest (23 features), done in n8n.
// Rules follow the "Web page phishing detection" dataset (Hannousse & Yahiouche, 2021) the model was trained on,
// including its encodings: domain_in_title = 1 means the domain is NOT in the page title.
// This node computes the 16 URL features + 4 page features; the 3 lookup features are added by "Assemble Model Features".
const ctx = $('Compute URL Hash').first().json;
// Firecrawl data comes from the Scrapping and Search Agent's structured output
const scrape = { data: $input.first().json.output?.Data?.FireCrawl ?? {} };
const url = ctx.normalisedUrl;

// ---- registered-domain split (compact public-suffix rules; no tldextract in the Code node) ----
const SECOND_LEVEL = new Set(['co','com','net','org','gov','edu','ac','gob','go','or','ne','mil','nic','sch','ltd','plc',
  'nom','web','gen','firm','info','biz','int','res','ind','govt','mod','nhs','police','lg','gv','muni','in','my']);
const NOT_SUFFIX = new Set(['biz.ua','co.nf','co.ua','co.vu','com.ru','gov.ru','nic.ru','org.ru']);
const EXTRA_SUFFIX = new Set(['k12.mo.us','biella.it','blog.br','bologna.it','dp.ua','fg.it','gouv.fr','il.us','kalisz.pl',
  'kiev.ua','lviv.ua','me.uk','mk.ua','mn.us','od.ua','srv.br','stargard.pl','utazas.hu','waw.pl','zp.ua']);

function hostOf(u) {
  const m = u.match(/^[a-z][a-z0-9+.-]*:\/\/([^\/?#]*)/i);
  let netloc = m ? m[1] : u.split(/[\/?#]/)[0];
  netloc = netloc.slice(netloc.lastIndexOf('@') + 1);         // drop user:pass@
  if (netloc.startsWith('[')) return netloc.slice(1, netloc.indexOf(']')).toLowerCase();
  return netloc.replace(/:\d*$/, '').toLowerCase();
}

function splitHost(host) {
  const labels = host.split('.').filter(Boolean);
  if (/^\d+(\.\d+){3}$/.test(host) || host.includes(':')) return { subdomain: '', domain: host, suffix: '' };
  let n = 0;
  if (labels.length >= 4 && EXTRA_SUFFIX.has(labels.slice(-3).join('.'))) n = 3;
  else if (labels.length >= 3) {
    const two = labels.slice(-2).join('.');
    if (EXTRA_SUFFIX.has(two) || (!NOT_SUFFIX.has(two) && labels[labels.length - 1].length === 2 && SECOND_LEVEL.has(labels[labels.length - 2]))) n = 2;
  }
  if (!n && labels.length >= 2 && /^[a-z]{2,}$|^xn--/.test(labels[labels.length - 1])) n = 1;
  if (!n) return { subdomain: labels.slice(0, -1).join('.'), domain: labels[labels.length - 1] ?? '', suffix: '' };
  return { subdomain: labels.slice(0, -n - 1).join('.'), domain: labels[labels.length - n - 1] ?? '', suffix: labels.slice(-n).join('.') };
}

// ---- URL features (16) ----
const HINTS = ['wp','login','includes','admin','content','site','images','js','alibaba','css','myaccount','dropbox','themes','plugins','signin','view'];
const IP_PATTERN = new RegExp(
  '(([01]?\\d\\d?|2[0-4]\\d|25[0-5])\\.([01]?\\d\\d?|2[0-4]\\d|25[0-5])\\.([01]?\\d\\d?|2[0-4]\\d|25[0-5])\\.([01]?\\d\\d?|2[0-4]\\d|25[0-5])\\/)|' +
  '((0x[0-9a-fA-F]{1,2})\\.(0x[0-9a-fA-F]{1,2})\\.(0x[0-9a-fA-F]{1,2})\\.(0x[0-9a-fA-F]{1,2})\\/)|' +
  '(?:[a-fA-F0-9]{1,4}:){7}[a-fA-F0-9]{1,4}|[0-9a-fA-F]{7}');
const words = (s) => s.toLowerCase().split(/[-./?=@&%:_]/).filter(Boolean);
const digitRatio = (s) => s.length ? (s.match(/\d/g) || []).length / s.length : 0;
const count = (s, sub) => s.split(sub).length - 1;
const minLen = (ws) => ws.length ? Math.min(...ws.map(w => w.length)) : 0;
const maxLen = (ws) => ws.length ? Math.max(...ws.map(w => w.length)) : 0;

function urlFeatures(url) {
  const hostname = hostOf(url);
  const { subdomain, domain, suffix } = splitHost(hostname);
  // dataset quirk: the "path" is whatever follows the first "/" after the first occurrence of the suffix text
  const fromSuffix = url.slice(Math.max(url.indexOf(suffix), 0));
  const slash = fromSuffix.indexOf('/');
  const path = slash === -1 ? '' : fromSuffix.slice(slash + 1);
  const wHost = [...words(domain), ...words(subdomain)];
  const wPath = words(path);
  const wRaw = [...words(domain), ...wPath, ...words(subdomain)];
  const lower = url.toLowerCase();
  return {
    features: {
      length_url: url.length,
      length_hostname: hostname.length,
      ip: IP_PATTERN.test(url) ? 1 : 0,
      nb_dots: count(url, '.'),
      nb_qm: count(url, '?'),
      nb_eq: count(url, '='),
      nb_slash: count(url, '/'),
      nb_www: wRaw.filter(w => w.includes('www')).length,
      ratio_digits_url: digitRatio(url),
      ratio_digits_host: digitRatio(hostname),
      tld_in_subdomain: count(subdomain, suffix) > 0 || suffix === '' ? 1 : 0,
      prefix_suffix: /https?:\/\/[^\-]+-[^\-]+\//.test(url) ? 1 : 0,
      shortest_word_host: minLen(wHost),
      longest_words_raw: maxLen(wRaw),
      longest_word_path: maxLen(wPath),
      phish_hints: HINTS.reduce((n, h) => n + count(lower, h), 0),
    },
    hostname, domain, suffix,
    registeredDomain: suffix ? `${domain}.${suffix}` : domain,
  };
}

// ---- page features (4) from the Firecrawl HTML ----
const NULL_LINKS = new Set(['', '#', '#nothing', '#doesnotexist', '#null', '#void', '#whatever', '#content',
  'javascript::void(0)', 'javascript::void(0);', 'javascript::;', 'javascript']);
const LINK_ATTR = { a: 'href', link: 'href', script: 'src', img: 'src', audio: 'src', embed: 'src', iframe: 'src', form: 'action' };

function pageFeatures(u, html, title) {
  const { hostname, domain, registeredDomain } = u;
  let internals = 0, externals = 0, nulls = 0;
  if (html) {
    const clean = html.replace(/<!--[\s\S]*?-->/g, '').replace(/(<script\b[^>]*>)[\s\S]*?<\/script>/gi, '$1</script>');
    const tagRe = /<(a|link|script|img|audio|embed|iframe|form)\b([^>]*)>/gi;
    let t;
    while ((t = tagRe.exec(clean))) {
      const attr = LINK_ATTR[t[1].toLowerCase()];
      const a = t[2].match(new RegExp(`(?:^|\\s)${attr}\\s*=\\s*(?:"([^"]*)"|'([^']*)'|([^\\s"'>]+))`, 'i'));
      if (!a) continue;
      const link = a[1] ?? a[2] ?? a[3] ?? '';
      const isHttp = link.startsWith('http');
      if (link.includes(hostname) || link.includes(registeredDomain) || count(link, '.') === 1 || !isHttp) {
        if (!isHttp && NULL_LINKS.has(link.trim().toLowerCase())) nulls++;
        else internals++;
      } else externals++;
    }
    if (!title) title = (clean.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '';
  }
  const total = internals + externals + nulls;
  const pageTitle = String(title || '').trim();
  return {
    nb_hyperlinks: total,
    ratio_intHyperlinks: total ? internals / total : 0,
    empty_title: pageTitle ? 0 : 1,
    domain_in_title: domain && pageTitle.toLowerCase().includes(domain.toLowerCase()) ? 0 : 1,
  };
}

const u = urlFeatures(url);
const html = scrape?.data?.rawHtml ?? scrape?.data?.html ?? null;
const title = scrape?.data?.metadata?.title ?? null;

return [{ json: {
  url,
  registeredDomain: u.registeredDomain,
  hasHtml: !!html,
  features: { ...u.features, ...pageFeatures(u, html, title) },
} }];

// Adds the 3 lookup features to the 20 computed ones and builds the 23-feature payload for ml-service.
// Dataset encodings: google_index = 1 means NOT indexed; domain_age = -1 when unknown.
// A lookup that failed (or has no credential yet) falls back to a default and is listed in missing_features.
const base = $('Extract Model Features1').first().json;
const read = (name) => { try { return $(name).first().json ?? {}; } catch (e) { return {}; } };
const agentData = read('Scrapping and Search Agent').output?.Data ?? {};
const rdap = agentData.RDAP ?? {};
const serp = agentData.SerpAPI ?? {};
const opr = agentData.OpenRank ?? {};

const missing = [];
const orDefault = (name, value, fallback) => {
  if (value === null || value === undefined || Number.isNaN(value)) { missing.push(name); return fallback; }
  return value;
};

// domain_age: days since the RDAP "registration" event
const registered = (rdap.events ?? []).find(e => e.eventAction === 'registration')?.eventDate;
const domainAge = registered ? Math.floor((Date.now() - new Date(registered).getTime()) / 86400000) : null;

// google_index: SerpApi search for "site:<url>"
const serpOk = serp.search_metadata?.status === 'Success';
const googleIndex = serpOk ? ((serp.organic_results ?? []).length ? 0 : 1) : null;

// page_rank: Open PageRank integer 0-10 (unknown domains come back as 0, as in the dataset)
const oprItem = Array.isArray(opr.response) ? opr.response[0] : null;
const pageRank = oprItem ? Number(oprItem.page_rank_integer || 0) : null;

const f = base.features;
const features = {
  length_url: f.length_url,
  length_hostname: f.length_hostname,
  ip: f.ip,
  nb_dots: f.nb_dots,
  nb_qm: f.nb_qm,
  nb_eq: f.nb_eq,
  nb_slash: f.nb_slash,
  nb_www: f.nb_www,
  ratio_digits_url: f.ratio_digits_url,
  ratio_digits_host: f.ratio_digits_host,
  tld_in_subdomain: f.tld_in_subdomain,
  prefix_suffix: f.prefix_suffix,
  shortest_word_host: f.shortest_word_host,
  longest_words_raw: f.longest_words_raw,
  longest_word_path: f.longest_word_path,
  phish_hints: f.phish_hints,
  nb_hyperlinks: f.nb_hyperlinks,
  ratio_intHyperlinks: f.ratio_intHyperlinks,
  empty_title: f.empty_title,
  domain_in_title: f.domain_in_title,
  domain_age: orDefault('domain_age', domainAge, -1),
  google_index: orDefault('google_index', googleIndex, 0),
  page_rank: orDefault('page_rank', pageRank, 0),
};
if (!base.hasHtml) missing.push('nb_hyperlinks', 'ratio_intHyperlinks');

return [{ json: { url: base.url, features, missing_features: missing } }];

