const j = $input.first().json;
const safeUrl = j.submittedUrl ? j.submittedUrl.replace(/\./g, '[.]') : '';
const badScheme = j.urls?.[0]?.scheme;

const ERROR_MESSAGES = {
  NO_URL: `⚠️ I couldn't find a link in your message. Please send the full web address (starting with http:// or https://).`,
  MISSING_SCHEME: `⚠️ That link (${safeUrl}) is missing http:// or https://. Please send the full address including the protocol.`,
  MALFORMED: `⚠️ I couldn't read that link (${safeUrl}). Please check for typos and send the full address again.`,
  INVALID_HOST: `⚠️ That link (${safeUrl}) doesn't have a valid domain or IP address. Please check it and try again.`,
  INVALID_PORT: `⚠️ That link (${safeUrl}) uses an invalid port number. Please check it and try again.`,
  TOO_LONG: `⚠️ That link is too long to scan (maximum 2,048 characters).`,
  UNSUPPORTED_SCHEME: `⚠️ That link (${safeUrl}) uses an unsupported protocol${badScheme ? ` (${badScheme}://)` : ''}. Only public http:// or https:// web addresses are supported—please check for typos and try again.`,
  PRIVATE_HOST: `⚠️ That link (${safeUrl}) points to a private or local network address. Only public http/https web addresses can be scanned.`,
  DANGEROUS_SCHEME: `🚨 That message contains a potentially dangerous link type (${(j.dangerousSchemes || []).join(', ')}) that browsers and devices should not open. Do not click or run it.`,
};

const replyText = ERROR_MESSAGES[j.reason] || `⚠️ I couldn't process that link. Please check it and try again.`;

return [{ json: { ...j, replyText } }];

const item = $input.first().json;
const checks = item.checks || [];

const jailbreakCheck = checks.find(c => c.name === 'jailbreak');
const outOfScopeCheck = checks.find(c => c.name === 'OutOFScope');

const message1 = (jailbreakCheck && jailbreakCheck.confidenceScore > 0.5)
  ? "Your message goes against our company policy."
  : null;

const message2 = (outOfScopeCheck && outOfScopeCheck.confidenceScore > 0.5)
  ? "I cannot help you with this query. What you are requesting is out of scope of my capabilities."
  : null;

// Join only the triggered messages with a newline (avoids printing "null" or extra blank lines)
const combinedMessage = [message1, message2].filter(Boolean).join('\n') || null;

return [{
  json: {
    ...item,
    message1,
    message2,
    combinedMessage,
  }
}];

